/* Define those to better describe your network interface. */
#define IFNAME0 'e'
#define IFNAME1 'n'

#if LWIP_NETIF_STATUS_CALLBACK == 1
extern void netif_status_callback(struct netif *netif);
#endif

#if LWIP_NETIF_LINK_CALLBACK == 1
extern void netif_link_callback(struct netif *netif);
#endif


/**
 * Should be called at the beginning of the program to set up the
 * network interface. It calls the function low_level_init() to do the
 * actual setup of the hardware.
 *
 * This function should be passed as a parameter to netif_add().
 *
 * @param netif the lwip network interface structure for this ethernetif
 * @return ERR_OK if the loopif is initialized
 *         ERR_MEM if private data couldn't be allocated
 *         any other err_t on error
 */
err_t ethernetif_init(struct netif *netif)
{
    ethernetif_t *ethif = (ethernetif_t *)netif->state;

    LWIP_ASSERT("netif != NULL", (netif != NULL));

    netif->name[0] = IFNAME0;
    netif->name[1] = IFNAME1;

#if LWIP_NETIF_HOSTNAME
    if (netif->hostname == NULL)
    {
        /* Initialize interface hostname */
        netif->hostname = "lwip";
    }
#endif /* LWIP_NETIF_HOSTNAME */

#if LWIP_IPV6
    netif->output_ip6 = ethip6_output;
#endif /* LWIP_IPV6 */

    netif->output = etharp_output;
    netif->linkoutput = ethif->low_level_output;

    netif->hwaddr_len = ETH_HWADDR_LEN;
    SMEMCPY(netif->hwaddr, ethif->macaddr, ETH_HWADDR_LEN);

    /* maximum transfer unit */
    netif->mtu = 1500U;

    /* device capabilities */
    netif->flags = NETIF_FLAG_BROADCAST | NETIF_FLAG_ETHARP;

#if LWIP_IPV6 && LWIP_IPV6_MLD
    /*
     * For hardware/netifs that implement MAC filtering.
     * All-nodes link-local is handled by default, so we must let the hardware know
     * to allow multicast packets in.
     * Should set mld_mac_filter previously. */
    if (netif->mld_mac_filter != NULL)
    {
        ip6_addr_t ip6_allnodes_ll;
        ip6_addr_set_allnodes_linklocal(&ip6_allnodes_ll);
        netif->mld_mac_filter(netif, &ip6_allnodes_ll, NETIF_ADD_MAC_FILTER);
    }
#endif /* LWIP_IPV6 && LWIP_IPV6_MLD */

    /*  Registers the default network interface.*/
    netif_set_default(netif);

    /* If callback enabled */
#if LWIP_NETIF_STATUS_CALLBACK == 1
    /* Initialize interface status change callback */
    netif_set_status_callback(netif, netif_status_callback);
#endif

#if LWIP_NETIF_LINK_CALLBACK == 1
    netif_set_link_callback(netif, netif_link_callback);
#endif

    return ERR_OK;
}

#if defined(IFX_DEVICE_HAS_GETH)

/**
 * This function should do the actual transmission of the packet. The packet is
 * contained in the pbuf that is passed to the function. This pbuf
 * might be chained.
 *
 * @param netif the lwip network interface structure for this ethernetif
 * @param p the MAC packet to send (e.g. IP packet including MAC addresses and type)
 * @return ERR_OK if the packet could be sent
 *         an err_t value if the packet couldn't be sent
 *
 * @note Returning ERR_MEM here if a DMA queue of your MAC is full can lead to
 *       strange results. You might consider waiting for space in the DMA queue
 *       to become available since the stack doesn't retry to send a packet
 *       dropped because of memory failure (except for the TCP timers).
 */
err_t geth_low_level_output(struct netif *netif, struct pbuf *p)
{
    ethernetif_t *ethif = (ethernetif_t *)netif->state;
    IfxGeth_Eth *geth = (IfxGeth_Eth *)ethif->handle;
    IfxGeth_TxDmaChannel tx_dma_channel = ethif->tx_dma_channel;

    uint8 *buffer = IfxGeth_Eth_getTransmitBuffer(geth, tx_dma_channel);
    if (buffer != NULL)
    {

#if ETH_PAD_SIZE
        pbuf_header(p, -ETH_PAD_SIZE);    /* Drop the padding word */
#endif

        sint32 framelen = 0U;
        for(struct pbuf *q = p; q != NULL; q = q->next)
        {
            /* Send the data from the pbuf to the interface, one pbuf at a
               time. The size of the data in each pbuf is kept in the ->len
               variable. */
            MEMCPY(buffer, q->payload, q->len);
            framelen += (uint32)q->len;
            buffer += q->len;
        }

#if ETH_PAD_SIZE
        pbuf_header(p, ETH_PAD_SIZE);    /* Reclaim the padding word */
#endif

        /* This iLLD version exposes IfxGeth_Eth_sendTransmitBuffer(geth,
         * portIndex, packetLength, channelId) rather than the TC489 "...Ex"
         * variant used by the vendored source. */
        IfxGeth_Eth_sendTransmitBuffer(geth, (IfxGeth_PortIndex)ethif->port_index,
                                       (uint32)framelen, tx_dma_channel);

        LINK_STATS_INC(link.xmit);
        return ERR_OK;
    }
    else
    {
        return ERR_MEM;
    }

}

/**
 * Should allocate a pbuf and transfer the bytes of the incoming
 * packet from the interface into the pbuf.
 *
 * @param netif the lwip network interface structure for this ethernetif
 * @return a pbuf filled with the received packet (including MAC header)
 *         NULL on memory error
 */
struct pbuf *geth_low_level_input(struct netif *netif)
{
    ethernetif_t *ethif = (ethernetif_t *)netif->state;
    IfxGeth_Eth *geth = (IfxGeth_Eth *)ethif->handle;
    IfxGeth_RxDmaChannel rx_dma_channel = ethif->rx_dma_channel;

    struct pbuf *p = NULL;

    volatile IfxGeth_RxDescr *rx_desc = IfxGeth_Eth_getActualRxDescriptor(geth, rx_dma_channel);
    if (rx_desc->RDES3.W.OWN == 0)
    {
        if (rx_desc->RDES3.W.CTXT == 0)
        {
            if ((rx_desc->RDES3.W.FD == 1) && (rx_desc->RDES3.W.LD == 1) && (rx_desc->RDES3.W.ES == 0))
            {
                size_t len = rx_desc->RDES3.W.PL - 4;
                uint8 *buffer = (uint8*)IfxGeth_Eth_getReceiveBuffer(geth, rx_dma_channel);
                if (buffer != NULL)
                {
#if ETH_PAD_SIZE
                    len += ETH_PAD_SIZE;    /* allow room for Ethernet padding */
#endif

                    /* We allocate a pbuf chain of pbufs from the pool. */
                    p = pbuf_alloc(PBUF_RAW, (u16_t)len, PBUF_POOL);
                    if (p != NULL)
                    {

#if ETH_PAD_SIZE
                        pbuf_header(p, -ETH_PAD_SIZE);  /* drop the padding word */
#endif

                        len = 0U;
                        /* We iterate over the pbuf chain until we have read the entire
                         * packet into the pbuf. */
                        for (struct pbuf *q = p; q != NULL; q = q->next)
                        {
                            /* Read enough bytes to fill this pbuf in the chain. The
                             * available data in the pbuf is given by the q->len
                             * variable.
                             * This does not necessarily have to be a memcpy, you can also preallocate
                             * pbufs for a DMA-enabled MAC and after receiving truncate it to the
                             * actually received size. In this case, ensure the tot_len member of the
                             * pbuf is the sum of the chained pbuf len members.
                             */
                            MEMCPY(q->payload, buffer, q->len);
                            len += q->len;
                            buffer += q->len;
                         }

#if ETH_PAD_SIZE
                         pbuf_header(p, ETH_PAD_SIZE);    /* Reclaim the padding word */
#endif
                         LINK_STATS_INC(link.recv);
                    }
                    else
                    {
                        LINK_STATS_INC(link.memerr);
                        LINK_STATS_INC(link.drop);
                    }
                }
                else
                {
                    LINK_STATS_INC(link.memerr);
                    LINK_STATS_INC(link.drop);
                }

            }
        }
        else
        {
            /* context descriptor */
        }
        /* This iLLD version returns the buffer to the DMA (OWN=1) and advances
         * to the next RX descriptor in a single call (the TC489 source split
         * this into returnRxDescriptor + updateActualRxDescriptor). */
        IfxGeth_Eth_shuffleRxDescriptor(geth, rx_dma_channel);

    }
    return p;

}

#endif

#if defined(IFX_DEVICE_HAS_LETH)

/**
 * This function should do the actual transmission of the packet. The packet is
 * contained in the pbuf that is passed to the function. This pbuf
 * might be chained.
 *
 * @param netif the lwip network interface structure for this ethernetif
 * @param p the MAC packet to send (e.g. IP packet including MAC addresses and type)
 * @return ERR_OK if the packet could be sent
 *         an err_t value if the packet couldn't be sent
 *
 * @note Returning ERR_MEM here if a DMA queue of your MAC is full can lead to
 *       strange results. You might consider waiting for space in the DMA queue
 *       to become available since the stack doesn't retry to send a packet
 *       dropped because of memory failure (except for the TCP timers).
 */
err_t leth_low_level_output(struct netif *netif, struct pbuf *p)
{
    ethernetif_t *ethif = (ethernetif_t *)netif->state;
    IfxLeth_Eth *leth = (IfxLeth_Eth *)ethif->handle;
    IfxLeth_TxDmaChannel tx_dma_channel = ethif->tx_dma_channel;

    uint8 *buffer = IfxLeth_Eth_getTransmitBuffer(leth, tx_dma_channel);
    if (buffer != NULL)
    {

#if ETH_PAD_SIZE
        pbuf_header(p, -ETH_PAD_SIZE);    /* Drop the padding word */
#endif

        sint32 framelen = 0U;
        for(struct pbuf *q = p; q != NULL; q = q->next)
        {
            /* Send the data from the pbuf to the interface, one pbuf at a
               time. The size of the data in each pbuf is kept in the ->len
               variable. */
            MEMCPY(buffer, q->payload, q->len);
            framelen += (uint32)q->len;
            buffer += q->len;
        }

#if ETH_PAD_SIZE
        pbuf_header(p, ETH_PAD_SIZE);    /* Reclaim the padding word */
#endif

        IfxLeth_Eth_sendTransmitBufferEx(leth, tx_dma_channel, framelen, FALSE);

        LINK_STATS_INC(link.xmit);
        return ERR_OK;
    }
    else
    {
        return ERR_MEM;
    }

}

/**
 * Should allocate a pbuf and transfer the bytes of the incoming
 * packet from the interface into the pbuf.
 *
 * @param netif the lwip network interface structure for this ethernetif
 * @return a pbuf filled with the received packet (including MAC header)
 *         NULL on memory error
 */
struct pbuf *leth_low_level_input(struct netif *netif)
{
    ethernetif_t *ethif = (ethernetif_t *)netif->state;
    IfxLeth_Eth *leth = (IfxLeth_Eth *)ethif->handle;
    IfxLeth_RxDmaChannel rx_dma_channel = ethif->rx_dma_channel;

    struct pbuf *p = NULL;

    volatile IfxLeth_RxDescr *rx_desc = IfxLeth_Eth_getActualRxDescriptor(leth, rx_dma_channel);
    if (rx_desc->RDES3.W.OWN == 0)
    {
        if (rx_desc->RDES3.W.CTXT == 0)
        {
            if ((rx_desc->RDES3.W.FD == 1) && (rx_desc->RDES3.W.LD == 1) && (rx_desc->RDES3.W.ES == 0))
            {
                size_t len = rx_desc->RDES3.W.PL - 4;
                uint8 *buffer = (uint8*)IfxLeth_Eth_getReceiveBuffer(leth, rx_dma_channel);
                if (buffer != NULL)
                {
#if ETH_PAD_SIZE
                    len += ETH_PAD_SIZE;    /* allow room for Ethernet padding */
#endif

                    /* We allocate a pbuf chain of pbufs from the pool. */
                    p = pbuf_alloc(PBUF_RAW, (u16_t)len, PBUF_POOL);
                    if (p != NULL)
                    {

#if ETH_PAD_SIZE
                        pbuf_header(p, -ETH_PAD_SIZE);  /* drop the padding word */
#endif

                        len = 0U;
                        /* We iterate over the pbuf chain until we have read the entire
                         * packet into the pbuf. */
                        for (struct pbuf *q = p; q != NULL; q = q->next)
                        {
                            /* Read enough bytes to fill this pbuf in the chain. The
                             * available data in the pbuf is given by the q->len
                             * variable.
                             * This does not necessarily have to be a memcpy, you can also preallocate
                             * pbufs for a DMA-enabled MAC and after receiving truncate it to the
                             * actually received size. In this case, ensure the tot_len member of the
                             * pbuf is the sum of the chained pbuf len members.
                             */
                            MEMCPY(q->payload, buffer, q->len);
                            len += q->len;
                            buffer += q->len;
                         }

#if ETH_PAD_SIZE
                         pbuf_header(p, ETH_PAD_SIZE);    /* Reclaim the padding word */
#endif
                         LINK_STATS_INC(link.recv);
                    }
                    else
                    {
                        LINK_STATS_INC(link.memerr);
                        LINK_STATS_INC(link.drop);
                    }
                }
                else
                {
                    LINK_STATS_INC(link.memerr);
                    LINK_STATS_INC(link.drop);
                }

            }
        }
        else
        {
            /* context descriptor */
        }
        IfxLeth_Eth_returnRxDescriptor(leth, rx_dma_channel);
        IfxLeth_Eth_updateActualRxDescriptor(leth, rx_dma_channel);

    }
    return p;

}

#endif /* IFX_DEVICE_HAS_LETH */

